/** OPENAPI_YAML is the REST API's OpenAPI description, GET /openapi.yaml. */
export const OPENAPI_YAML: string =
    '# SPDX-FileCopyrightText: (c) 2026 Rafal Zajac.\n# SPDX-License-Identifier: MIT\nopenapi: 3.2.0\ninfo:\n  title: docket REST API\n  version: "1.0.0"\n  summary: REST mirror of the docket documentation server.\n  description: >\n    Plain REST access to the Markdown corpus served by docket. The same\n    engine also serves MCP (Streamable HTTP) at /mcp; that JSON-RPC surface is\n    intentionally not described by this document — its tools are discovered\n    through MCP\'s own tools/list mechanism. The corpus is indexed at process\n    start; a corpus change requires a server restart unless the server\n    watches its sources, in which case it rebuilds the index shortly after\n    the change.\n  license:\n    name: MIT\n    identifier: MIT\npaths:\n  /healthz:\n    get:\n      summary: Liveness probe\n      description: >\n        Reports that the server is up and how many documents it has indexed.\n      operationId: getHealth\n      responses:\n        "200":\n          description: Server is healthy.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Health"\n  /search:\n    get:\n      summary: Search the corpus\n      description: >\n        Ranks corpus sections against the free-text query with BM25 and\n        returns the most relevant sections with citation metadata and the\n        source document\'s trust rank. The rank never reorders the results.\n        The response shape mirrors the MCP search tool field for field.\n      operationId: search\n      parameters:\n        - name: q\n          in: query\n          required: true\n          description: The free-text search query.\n          schema:\n            type: string\n            minLength: 1\n        - name: k\n          in: query\n          required: false\n          description: Maximum number of results; defaults to 10.\n          schema:\n            type: integer\n            minimum: 1\n            maximum: 100\n            default: 10\n      responses:\n        "200":\n          description: Ranked sections, best match first.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/SearchResponse"\n        "400":\n          description: Missing q, or k is not a positive integer.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n  /docs:\n    get:\n      summary: List every document\n      description: >\n        Returns the identity, path, trust rank, and title of every indexed\n        document, sorted by path. Mirrors the MCP list_docs tool.\n      operationId: listDocs\n      responses:\n        "200":\n          description: The corpus inventory.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/DocList"\n  /docs/{id}:\n    get:\n      summary: Get one whole document\n      description: >\n        Returns the complete source file for the given document identity or\n        current path, read from disk at request time. Mirrors the MCP get_doc\n        tool.\n      operationId: getDoc\n      parameters:\n        - name: id\n          in: path\n          required: true\n          description: >\n            The document\'s identity (id) or current path, as reported by\n            /search and /docs; an identity is tried first. Deliberate\n            deviation from strict path-template semantics: the value may\n            contain "/" separators and is matched as the remainder of the URL\n            path after /docs/. Values holding characters such as "#", "?", or\n            spaces must be URL-encoded.\n          schema:\n            type: string\n            minLength: 1\n      responses:\n        "200":\n          description: The whole document with citation metadata.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Document"\n        "404":\n          description: No document with the given identity or path is indexed.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n  /openapi.yaml:\n    get:\n      summary: This document\n      operationId: getOpenAPI\n      responses:\n        "200":\n          description: The OpenAPI description of this API.\n          content:\n            application/yaml: {}\n  /glossary:\n    get:\n      summary: List the glossary\'s defined terms\n      description: >\n        Returns every term the configured glossary defines (each "## "\n        heading of its documents), ordered by document path and then by\n        position in the document, read from disk at request time. Mirrors\n        the MCP glossary_terms tool. Present only when the server is\n        configured with a glossary.\n      operationId: glossaryTerms\n      parameters:\n        - name: term\n          in: query\n          required: false\n          description: >\n            Keep only terms whose heading contains this text, ignoring case;\n            omit to return every term.\n          schema:\n            type: string\n      responses:\n        "200":\n          description: The defined terms.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/GlossaryTerms"\n  /gaps:\n    get:\n      summary: List gaps\n      description: >\n        Returns the recorded gaps of the gaps folder and its closed\n        subfolder, each with its front-matter fields, body sections, and\n        file path, optionally filtered by status, SRD reference, the\n        people to ask, and whether the questions were sent, in id order. With query, only the gaps matching it are\n        returned, ranked by relevance (best first), each with a score; the\n        filters still apply. A filled or open gap whose filled_by sections\n        changed, vanished, or were never hashed carries stale and\n        stale_refs; its status is unchanged. A gap file that fails to parse\n        or breaks the gap format (a missing or unknown key value, a file name\n        disagreeing with its id, a missing body section, a number shared\n        with another file) is left out of gaps and listed under invalid,\n        whatever the filters; every operation on its gap answers 409 until\n        the file is fixed, and the server never rewrites or deletes it. Gaps\n        never appear in /search. Mirrors the MCP list_gaps tool. Present\n        only when the server is configured with a gaps folder.\n      operationId: listGaps\n      parameters:\n        - name: status\n          in: query\n          required: false\n          description: >\n            Keep only gaps in this status; omit to return all.\n          schema:\n            type: string\n            enum: [draft, open, filled, wontfix]\n        - name: srd_ref\n          in: query\n          required: false\n          description: >\n            Keep only gaps whose srd_ref contains this text, for example an\n            SRD folder name; omit to return all.\n          schema:\n            type: string\n        - name: query\n          in: query\n          required: false\n          description: >\n            Free-text query ranked with BM25 against each gap\'s topic\n            (boosted), search terms, demand, detail, target claim, and\n            srd_ref. Keeps only matching gaps, best first, each with a\n            score; omit to list in id order.\n          schema:\n            type: string\n        - name: stale\n          in: query\n          required: false\n          description: >\n            true keeps only stale gaps; false or omitted applies no stale\n            filter.\n          schema:\n            type: boolean\n        - name: ask\n          in: query\n          required: false\n          description: >\n            Keep only gaps with a name in ask containing this text, case\n            ignored; omit to return all.\n          schema:\n            type: string\n        - name: asked\n          in: query\n          required: false\n          description: >\n            true keeps only gaps whose questions were sent (asked set), false\n            only gaps whose questions were not sent; omit to apply no asked\n            filter.\n          schema:\n            type: boolean\n      responses:\n        "200":\n          description: The recorded gaps.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/GapList"\n        "400":\n          description: >\n            The status is not a recognised one, or stale or asked is not\n            true or false.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n    post:\n      summary: Report a gap\n      description: >\n        Records a gap, a fact SRD work needs that the corpus documents\n        outside the initiatives folder do not supply reliably, as a new\n        Markdown file in the gaps folder: open or, with draft set, an\n        unconfirmed draft. A gap closes only when the fact appears in a\n        corpus document outside the initiatives folder, never in an SRD and\n        never on a bare URL. doc_id, when given, must name a corpus document,\n        any one, by id or path and is stored as its id. ask names the people\n        who can answer the gap\'s question; asked is the date the questions\n        were sent to them. Mirrors the MCP report_gap tool. Present only when the server is configured with a gaps folder.\n      operationId: reportGap\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: "#/components/schemas/ReportGapRequest"\n      responses:\n        "201":\n          description: The gap was recorded.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/ReportGapResponse"\n        "400":\n          description: >\n            The request body is malformed, names an unknown kind or answer,\n            leaves topic, demand, detail, or an ask name blank, gives an\n            asked that is not YYYY-MM-DD, puts a level-1 or level-2\n            heading into a section, or names a doc_id that does not resolve.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "413":\n          description: The request body exceeds 1 MiB.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n  /gaps/{id}:\n    parameters:\n      - name: id\n        in: path\n        required: true\n        description: The gap ID, as reported by /gaps.\n        schema:\n          type: string\n          minLength: 1\n    put:\n      summary: Edit a gap\n      description: >\n        Changes the given fields of a draft or open gap; a field left out\n        keeps the value in the gap\'s file, so edits made to the file by hand\n        survive. add_hit counts one more encounter of the gap; ask replaces\n        the people who can answer, asked records the date the questions were\n        sent. Filled and wontfix gaps keep ask and asked as history. Mirrors\n        the MCP update_gap tool. Present only when the server is configured with a gaps folder.\n      operationId: updateGap\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: "#/components/schemas/UpdateGapRequest"\n      responses:\n        "200":\n          description: The gap was updated.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Ok"\n        "400":\n          description: >\n            The request body is malformed or changes nothing, or a field is\n            invalid as for POST /gaps.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "404":\n          description: No gap with the given ID exists.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "409":\n          description: >\n            The gap is filled or wontfix, so it cannot be edited, or the gap\'s file is invalid (listed\n            under invalid by GET /gaps); the file is left untouched.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "413":\n          description: The request body exceeds 1 MiB.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n    delete:\n      summary: Discard a draft gap\n      description: >\n        Deletes a draft gap\'s file. Only a draft can be deleted; deleting the\n        highest-numbered draft frees its number. Mirrors the MCP discard_gap\n        tool. Present only when the server is configured with a gaps folder.\n      operationId: discardGap\n      responses:\n        "200":\n          description: The draft was deleted.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Ok"\n        "404":\n          description: No gap with the given ID exists.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "409":\n          description: >\n            The gap is not a draft, so it cannot be deleted, or the gap\'s file is invalid (listed\n            under invalid by GET /gaps); the file is left untouched.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n  /gaps/{id}/submit:\n    post:\n      summary: Submit a draft gap\n      description: >\n        Confirms a draft gap, moving it to the open status. Takes no request\n        body. Mirrors the MCP submit_gap tool. Present only when the server is configured with a gaps folder.\n      operationId: submitGap\n      parameters:\n        - name: id\n          in: path\n          required: true\n          description: The gap ID, as reported by /gaps.\n          schema:\n            type: string\n            minLength: 1\n      responses:\n        "200":\n          description: The draft was submitted.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Ok"\n        "404":\n          description: No gap with the given ID exists.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "409":\n          description: >\n            The gap is not a draft, so it cannot be submitted, or the gap\'s file is invalid (listed\n            under invalid by GET /gaps); the file is left untouched.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n  /gaps/{id}/fill:\n    post:\n      summary: Fill a gap\n      description: >\n        Records the corpus sections that now state an open gap\'s fact, or\n        refreshes a filled gap\'s list. filled_by replaces the gap\'s list,\n        each entry naming a corpus document outside the initiatives folder,\n        never an SRD, and stored with the hash of its section\'s current\n        text. With\n        complete set an open gap moves to filled; otherwise it stays open,\n        partly filled, and remaining, when given, replaces its Detail section\n        with what is still missing. A filled gap takes only complete set: the\n        listed sections are re-hashed, clearing its stale flag, and it stays\n        filled. Mirrors the MCP fill_gap tool. Present only when the server is configured with a gaps folder.\n      operationId: fillGap\n      parameters:\n        - name: id\n          in: path\n          required: true\n          description: The gap ID, as reported by /gaps.\n          schema:\n            type: string\n            minLength: 1\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: "#/components/schemas/FillGapRequest"\n      responses:\n        "200":\n          description: The gap was filled, completely or in part, or refreshed.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Ok"\n        "400":\n          description: >\n            The request body is malformed, filled_by is empty, an entry does\n            not resolve to a corpus document or a heading in it, an entry\n            names a document under the initiatives folder, or remaining\n            holds a level-1 or level-2 heading.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "404":\n          description: No gap with the given ID exists.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "409":\n          description: >\n            The gap is neither open nor, for a complete fill, filled, or the\n            gap\'s file is invalid (listed\n            under invalid by GET /gaps); the file is left untouched.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "413":\n          description: The request body exceeds 1 MiB.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n  /gaps/{id}/reopen:\n    post:\n      summary: Reopen a filled gap\n      description: >\n        Moves a filled gap back to open, appending the reason to its Detail\n        section. Its filled_by list is kept, so it can be filled again with a\n        corrected list. Mirrors the MCP reopen_gap tool. Present only when the server is configured with a gaps folder.\n      operationId: reopenGap\n      parameters:\n        - name: id\n          in: path\n          required: true\n          description: The gap ID, as reported by /gaps.\n          schema:\n            type: string\n            minLength: 1\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: "#/components/schemas/ReasonRequest"\n      responses:\n        "200":\n          description: The gap was reopened.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Ok"\n        "400":\n          description: The request body is malformed or the reason blank.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "404":\n          description: No gap with the given ID exists.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "409":\n          description: >\n            The gap is not filled, so it cannot be reopened, or the gap\'s file is invalid (listed\n            under invalid by GET /gaps); the file is left untouched.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "413":\n          description: The request body exceeds 1 MiB.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n  /gaps/{id}/wontfix:\n    post:\n      summary: Close a gap as wontfix\n      description: >\n        Closes an open gap the corpus will not carry, appending the reason to\n        its Detail section. Mirrors the MCP wontfix_gap tool. Present only when the server is configured with a gaps folder.\n      operationId: wontfixGap\n      parameters:\n        - name: id\n          in: path\n          required: true\n          description: The gap ID, as reported by /gaps.\n          schema:\n            type: string\n            minLength: 1\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: "#/components/schemas/ReasonRequest"\n      responses:\n        "200":\n          description: The gap was closed as wontfix.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Ok"\n        "400":\n          description: The request body is malformed or the reason blank.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "404":\n          description: No gap with the given ID exists.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "409":\n          description: >\n            The gap is not open, so it cannot be closed, or the gap\'s file is invalid (listed\n            under invalid by GET /gaps); the file is left untouched.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\n        "413":\n          description: The request body exceeds 1 MiB.\n          content:\n            application/json:\n              schema:\n                $ref: "#/components/schemas/Error"\ncomponents:\n  schemas:\n    Health:\n      type: object\n      required: [status, docs]\n      properties:\n        status:\n          type: string\n          description: Always "ok" when the server responds.\n        docs:\n          type: integer\n          description: Number of indexed documents.\n    Section:\n      type: object\n      required: [title, id, path, text, score]\n      properties:\n        title:\n          type: string\n          description: The source document\'s title.\n        id:\n          type: string\n          description: >\n            The source document\'s identity: its front-matter id when set, else\n            its path. Store this value to refer to the document.\n        path:\n          type: string\n          description: >\n            The source document\'s current path,\n            "<source-name>/<relative-path>".\n        rank:\n          $ref: "#/components/schemas/Rank"\n        heading_path:\n          type: array\n          items:\n            type: string\n          description: Heading trail from the document root to the section.\n        text:\n          type: string\n          description: Raw Markdown of the section, heading line included.\n        score:\n          type: number\n          description: BM25 relevance score; higher ranks first.\n        source_url:\n          type: string\n          description: >\n            The source document\'s canonical URL: its front-matter url, else\n            the first URL in its body; the same for every section of the\n            document, with no section fragment. Absent when unknown.\n    Rank:\n      type: integer\n      minimum: 1\n      description: >\n        The document\'s trust rank from the project\'s precedence list: 1 is\n        the most trusted, the first listed folder. A document gets the\n        position of the longest listed folder it lies under; one under no\n        listed folder ranks last, one past the list\'s length. The field is\n        absent for a document under the project\'s initiatives folder, and\n        for every document when no precedence is configured (always under a\n        plain YAML config). Rank is metadata only and never changes the\n        order of search results.\n    SearchResponse:\n      type: object\n      required: [results]\n      properties:\n        results:\n          type: array\n          items:\n            $ref: "#/components/schemas/Section"\n    DocSummary:\n      type: object\n      required: [id, path, title]\n      properties:\n        id:\n          type: string\n          description: >\n            The document\'s identity: its front-matter id when set, else its\n            path. Store this value to refer to the document.\n        path:\n          type: string\n          description: >\n            The document\'s current path, "<source-name>/<relative-path>".\n        rank:\n          $ref: "#/components/schemas/Rank"\n        title:\n          type: string\n          description: The document\'s front-matter title.\n    DocList:\n      type: object\n      required: [docs]\n      properties:\n        docs:\n          type: array\n          items:\n            $ref: "#/components/schemas/DocSummary"\n    Document:\n      type: object\n      required: [id, path, title, text]\n      properties:\n        id:\n          type: string\n          description: >\n            The document\'s identity: its front-matter id when set, else its\n            path. Store this value to refer to the document.\n        path:\n          type: string\n          description: >\n            The document\'s current path, "<source-name>/<relative-path>".\n        rank:\n          $ref: "#/components/schemas/Rank"\n        title:\n          type: string\n          description: The document\'s front-matter title.\n        source_url:\n          type: string\n          description: The document\'s canonical URL, absent when unknown.\n        text:\n          type: string\n          description: The whole source file, front-matter included.\n    Error:\n      type: object\n      required: [error]\n      properties:\n        error:\n          type: string\n          description: Human-readable description of the failure.\n    FillRef:\n      type: object\n      required: [ref]\n      properties:\n        ref:\n          type: string\n          description: >\n            A corpus section, "<identity>#<anchor>", or a whole document,\n            "<identity>". The identity is the document\'s id, else its path;\n            the anchor is the GitHub-style slug of the section\'s heading\n            text: lowercase, every character other than a letter, digit,\n            space, "-", or "_" dropped, each space turned into "-", and a\n            heading repeating an earlier slug suffixed "-1", "-2", and so on.\n        hash:\n          type: string\n          description: >\n            Hex SHA-256 of the section\'s text when the entry was written:\n            the heading line through the line before the next heading of the\n            same or a higher level, or the whole body without front matter\n            for a document, CRLF line endings turned to LF and trailing\n            whitespace at its end dropped. Absent when the entry carries\n            none.\n    StaleRef:\n      type: object\n      required: [ref, reason]\n      properties:\n        ref:\n          type: string\n          description: The filled_by entry\'s ref as the gap file records it.\n        reason:\n          type: string\n          enum: [changed, vanished, unhashed]\n          description: >\n            changed when the section\'s current hash differs from the\n            recorded one, vanished when the document or heading no longer\n            resolves, unhashed when the entry records no hash.\n    Gap:\n      type: object\n      required:\n        - id\n        - status\n        - kind\n        - answer\n        - ask\n        - asked\n        - srd_ref\n        - doc_id\n        - heading_path\n        - search_terms\n        - hits\n        - created\n        - filled_by\n        - topic\n        - demand\n        - detail\n        - target_claim\n        - file\n      properties:\n        id:\n          type: string\n          description: The store-assigned identifier, "gap-NNNN".\n        status:\n          type: string\n          enum: [draft, open, filled, wontfix]\n          description: The gap\'s lifecycle position.\n        kind:\n          type: string\n          enum: [missing, wrong, incomplete, ambiguous]\n          description: How the corpus fails to supply the fact.\n        answer:\n          type: string\n          enum: ["", deferred, unknown]\n          description: >\n            deferred when someone knows but was not asked yet, unknown when\n            nobody has pinned it down, empty otherwise.\n        ask:\n          type: array\n          items:\n            type: string\n          description: >\n            The people who can answer the gap\'s question, as typed, without\n            case-insensitive duplicates; empty when none are named.\n        asked:\n          type: string\n          description: >\n            The date, YYYY-MM-DD, the questions were sent to the people in\n            ask; empty when they were not sent.\n        srd_ref:\n          type: string\n          description: The SRD, requirement, or session that needs the fact.\n        doc_id:\n          type: string\n          description: >\n            Identity of the corpus document the gap is about, empty when no\n            document covers the topic.\n        heading_path:\n          type: array\n          items:\n            type: string\n          description: Heading trail within doc_id the gap is about.\n        search_terms:\n          type: array\n          items:\n            type: string\n          description: Queries tried that did not supply the fact.\n        hits:\n          type: integer\n          minimum: 1\n          description: Times the gap was met in SRD work.\n        created:\n          type: string\n          format: date-time\n          description: When the server created the gap\'s file.\n        filled_by:\n          type: array\n          items:\n            $ref: "#/components/schemas/FillRef"\n          description: >\n            The corpus sections that state the fact: all of it for a filled\n            gap, part of it for an open one.\n        topic:\n          type: string\n          description: The gap\'s short label, the file\'s H1.\n        demand:\n          type: string\n          description: Why the SRD work needs the fact.\n        detail:\n          type: string\n          description: >\n            What the corpus says now and what is missing; for a partly\n            filled gap, what remains; for a wontfix gap, why.\n        target_claim:\n          type: string\n          description: The sentence the corpus should state, empty if unknown.\n        file:\n          type: string\n          description: >\n            The gap file\'s path within the gaps folder: its name for a draft\n            or open gap, closed/ and its name for a filled or wontfix gap\n            (the server moves the file on each such transition), for example\n            closed/gap-0007-epub-token-lifetime.md.\n        score:\n          type: number\n          description: >\n            Relevance to the query, higher ranks first; present only when\n            the listing was given a query.\n        stale:\n          type: boolean\n          description: >\n            True for a filled or open gap with a filled_by entry listed in\n            stale_refs; absent otherwise. The server never changes a status\n            for it.\n        stale_refs:\n          type: array\n          items:\n            $ref: "#/components/schemas/StaleRef"\n          description: >\n            The stale filled_by entries, in filled_by order; present only\n            when stale is true.\n    BadFile:\n      type: object\n      required: [file, reason]\n      properties:\n        file:\n          type: string\n          description: >\n            The invalid file\'s path within the gaps folder, led by closed/\n            for a file in the closed subfolder.\n        reason:\n          type: string\n          description: Why the file is invalid.\n    GapList:\n      type: object\n      required: [gaps, invalid]\n      properties:\n        gaps:\n          type: array\n          items:\n            $ref: "#/components/schemas/Gap"\n        invalid:\n          type: array\n          items:\n            $ref: "#/components/schemas/BadFile"\n          description: >\n            Every invalid gap file, by file-name number, then name, whatever\n            the filters; an empty list when there is none.\n    ReportGapRequest:\n      type: object\n      required: [kind, topic, demand, detail]\n      properties:\n        kind:\n          type: string\n          enum: [missing, wrong, incomplete, ambiguous]\n          description: How the corpus fails to supply the fact.\n        topic:\n          type: string\n          minLength: 1\n          description: Short one-line label for the needed fact.\n        doc_id:\n          type: string\n          description: >\n            Id or path of the corpus document the gap is about, from a search\n            or /docs result; stored as the document\'s id. Omit when no\n            document covers the topic.\n        heading_path:\n          type: array\n          items:\n            type: string\n          description: Heading trail within doc_id, copied from a result.\n        demand:\n          type: string\n          minLength: 1\n          description: Why the SRD work needs the fact.\n        detail:\n          type: string\n          minLength: 1\n          description: What the corpus says now and what is missing.\n        target_claim:\n          type: string\n          description: The sentence the corpus should state, when known.\n        search_terms:\n          type: array\n          items:\n            type: string\n          description: Queries tried that did not supply the fact.\n        srd_ref:\n          type: string\n          description: The SRD, requirement, or session that needs the fact.\n        answer:\n          type: string\n          enum: ["", deferred, unknown]\n          description: >\n            deferred when someone knows but was not asked yet, unknown when\n            nobody has pinned it down; omit otherwise.\n        ask:\n          type: array\n          items:\n            type: string\n            minLength: 1\n          description: >\n            Names of the people who can answer the gap\'s question, as the\n            user types them; trimmed, case-insensitive duplicates dropped.\n        asked:\n          type: string\n          format: date\n          description: >\n            The date the questions were sent to the people in ask, set once\n            the user confirms they were sent; omit otherwise.\n        draft:\n          type: boolean\n          default: false\n          description: >\n            Record the gap unconfirmed, in the draft status; omit to record\n            it open.\n      additionalProperties: false\n    ReportGapResponse:\n      type: object\n      required: [gap_id]\n      properties:\n        gap_id:\n          type: string\n          description: The assigned gap ID, "gap-NNNN".\n    UpdateGapRequest:\n      type: object\n      description: >\n        The fields to change; every field is optional and one left out keeps\n        the value in the gap\'s file. At least one field must be given.\n      properties:\n        kind:\n          type: string\n          enum: [missing, wrong, incomplete, ambiguous]\n        topic:\n          type: string\n          minLength: 1\n        doc_id:\n          type: string\n          description: Id or path of a corpus document; empty clears it.\n        heading_path:\n          type: array\n          items:\n            type: string\n        demand:\n          type: string\n          minLength: 1\n        detail:\n          type: string\n          minLength: 1\n        target_claim:\n          type: string\n        search_terms:\n          type: array\n          items:\n            type: string\n        srd_ref:\n          type: string\n        answer:\n          type: string\n          enum: ["", deferred, unknown]\n        ask:\n          type: array\n          items:\n            type: string\n            minLength: 1\n          description: >\n            Replaces the names of the people who can answer the gap\'s\n            question; an empty list clears them.\n        asked:\n          type: string\n          description: >\n            The date, YYYY-MM-DD, the questions were sent; empty clears it.\n        add_hit:\n          type: boolean\n          default: false\n          description: Count one more encounter of the gap in SRD work.\n      additionalProperties: false\n    FillGapRequest:\n      type: object\n      required: [filled_by]\n      properties:\n        filled_by:\n          type: array\n          minItems: 1\n          items:\n            type: string\n          description: >\n            The corpus sections stating the fact, each "<identity>#<anchor>"\n            or "<identity>" as for FillRef.ref, in a corpus document outside\n            the initiatives folder; a path is stored as the document\'s id.\n            Replaces the gap\'s list.\n        complete:\n          type: boolean\n          default: false\n          description: >\n            True when the sections state the whole fact, moving an open gap\n            to filled or refreshing a filled one; omit to keep an open gap\n            open, partly filled. A filled gap refuses an incomplete fill.\n        remaining:\n          type: string\n          description: >\n            Replaces the gap\'s Detail section: what is still missing.\n      additionalProperties: false\n    ReasonRequest:\n      type: object\n      required: [reason]\n      properties:\n        reason:\n          type: string\n          minLength: 1\n          description: Why, appended to the gap\'s Detail section.\n      additionalProperties: false\n    GlossaryTerm:\n      type: object\n      required: [term, name, abbreviation, id, path, anchor, definition]\n      properties:\n        term:\n          type: string\n          description: The heading text, for example "Stock Keeping Unit (SKU)".\n        name:\n          type: string\n          description: The term without its trailing parenthesised abbreviation.\n        abbreviation:\n          type: string\n          description: The text inside the trailing parentheses, empty if none.\n        id:\n          type: string\n          description: >\n            The defining document\'s identity: its front-matter id when set,\n            else its path. Store this value to refer to the document.\n        path:\n          type: string\n          description: >\n            The defining document\'s current path,\n            "<source-name>/<relative-path>".\n        anchor:\n          type: string\n          description: >\n            The GitHub-style slug of the term heading, as in\n            "maintenance-break-mb"; the anchor of a filled_by section\n            reference.\n        definition:\n          type: string\n          description: The first paragraph after the heading, as plain text.\n    GlossaryTerms:\n      type: object\n      required: [terms]\n      properties:\n        terms:\n          type: array\n          items:\n            $ref: "#/components/schemas/GlossaryTerm"\n    Ok:\n      type: object\n      required: [ok]\n      properties:\n        ok:\n          type: boolean\n          description: Always true when the operation succeeded.\n';
